package bin.nt.dex2c;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.regex.*;
import com.android.tools.smali.dexlib2.DexFileFactory;import com.android.tools.smali.dexlib2.dexbacked.DexBackedDexFile;import com.android.tools.smali.dexlib2.iface.*;
import bin.nt.dex2c.basic_blocks.BlockLifter;import bin.nt.dex2c.compiler.*;import bin.nt.dex2c.graph.Graph;import bin.nt.dex2c.graph.GraphBuilder;import bin.nt.dex2c.writer.CppWriter;
final class Compiler{
 private final Main.Cli cli;private final Pattern filter,classFilter,methodFilter;Compiler(Main.Cli c){cli=c;filter=p(c.filter);classFilter=p(c.classFilter);methodFilter=p(c.methodFilter);}private static Pattern p(String s){return s==null?null:Pattern.compile(s);}
 Main.Result compile(DexBackedDexFile dex,Path out)throws IOException{Files.createDirectories(out);Main.Result r=new Main.Result();StringBuilder cpp=new StringBuilder();cpp.append("#include <jni.h>\n#include <cstdint>\n#include <cmath>\n#include <limits>\n#include <string>\n\n");cpp.append("static jint nt_div_i(JNIEnv* e,jint a,jint b){if(!b){e->ThrowNew(e->FindClass(\"java/lang/ArithmeticException\"),\"/ by zero\");return 0;}if(a==INT32_MIN&&b==-1)return INT32_MIN;return a/b;}\n");cpp.append("static jint nt_rem_i(JNIEnv* e,jint a,jint b){if(!b){e->ThrowNew(e->FindClass(\"java/lang/ArithmeticException\"),\"/ by zero\");return 0;}if(a==INT32_MIN&&b==-1)return 0;return a%b;}\n");cpp.append("static jlong nt_div_l(JNIEnv* e,jlong a,jlong b){if(!b){e->ThrowNew(e->FindClass(\"java/lang/ArithmeticException\"),\"/ by zero\");return 0;}if(a==INT64_MIN&&b==-1)return INT64_MIN;return a/b;}\n");cpp.append("static jlong nt_rem_l(JNIEnv* e,jlong a,jlong b){if(!b){e->ThrowNew(e->FindClass(\"java/lang/ArithmeticException\"),\"/ by zero\");return 0;}if(a==INT64_MIN&&b==-1)return 0;return a%b;}\n");cpp.append("static jfloat nt_f32(uint32_t x){union{uint32_t i;jfloat f;}u{ x };return u.f;} static jdouble nt_f64(uint64_t x){union{uint64_t i;jdouble d;}u{ x };return u.d;}\n\n");
  for(ClassDef c:dex.getClasses())for(Method m:c.getMethods()){r.methods++;if(!selected(c,m))continue;try{Graph g=GraphBuilder.build(m);BlockLifter.lift(m,g);IrMethod ir=new SsaBuilder(g,m).build();cpp.append(new CppWriter().write(ir,cli.dynamicRegister));r.compiled++;}catch(Throwable t){r.unsupported++;cpp.append("\n/* FAILED ").append(safe(c.getType()+"->"+m.getName()+descriptor(m)+": "+t)).append(" */\n");}}
  Files.writeString(out.resolve("dex2c.cpp"),cpp,StandardCharsets.UTF_8);Files.writeString(out.resolve("compile-report.txt"),"methods="+r.methods+"\ncompiled="+r.compiled+"\nfailed="+r.unsupported+"\n",StandardCharsets.UTF_8);return r;}
 private boolean selected(ClassDef c,Method m){if(m.getImplementation()==null)return false;String x=c.getType()+"->"+m.getName()+descriptor(m);return(filter==null||filter.matcher(x).find())&&(classFilter==null||classFilter.matcher(c.getType()).find())&&(methodFilter==null||methodFilter.matcher(m.getName()).find());}
  private static String descriptor(Method m){StringBuilder x=new StringBuilder("(");for(CharSequence p:m.getParameterTypes())x.append(p);return x.append(")").append(m.getReturnType()).toString();}
 private static String safe(String x){return x.replace("*/","* /").replace("\n"," ");}
}
